<template><section v-loading="loading"><div class="toolbar"><el-upload :show-file-list="false" :auto-upload="false" accept=".csv,.xlsx" :on-change="change"><el-button type="primary">导入银行流水</el-button></el-upload><el-button :disabled="!selected.length" type="success" @click="confirm">确认所选匹配</el-button><el-button @click="load">刷新</el-button></div><el-alert title="系统仅生成匹配建议，必须由出纳或财务管理员人工确认。支持同一批次中一对多、多对一匹配。" type="info" show-icon class="notice" /><el-card shadow="never"><el-table :data="records" @selection-change="selectionChanged"><el-table-column type="selection" width="50" :selectable="selectable" /><el-table-column prop="bank_transaction_id" label="银行流水" min-width="250" /><el-table-column prop="payment_id" label="付款记录" min-width="250" /><el-table-column label="匹配金额" width="140"><template #default="{row}">{{formatMoney(row.matched_amount)}}</template></el-table-column><el-table-column label="置信度" width="150"><template #default="{row}"><el-progress :percentage="Math.round(Number(row.confidence)*100)" /></template></el-table-column><el-table-column prop="status" label="状态" width="120" /></el-table></el-card></section></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage,ElMessageBox,type UploadFile}from'element-plus';import{financeApi,formatMoney,type ReconciliationMatch}from'@/api/finance';const loading=ref(false),records=ref<ReconciliationMatch[]>([]),selected=ref<ReconciliationMatch[]>([]);function selectionChanged(rows:ReconciliationMatch[]){selected.value=rows}function selectable(row:ReconciliationMatch){return row.status==='suggested'}async function load(){loading.value=true;try{records.value=await financeApi.reconciliations()}finally{loading.value=false}}async function change(file:UploadFile){if(!file.raw)return;await financeApi.importStatement(file.raw);ElMessage.success('银行流水已导入并生成匹配建议');await load()}async function confirm(){await ElMessageBox.confirm(`确认 ${selected.value.length} 条对账匹配？`,'确认对账',{type:'warning'});await financeApi.confirmReconciliations(selected.value.map(item=>item.id));ElMessage.success('对账已确认');selected.value=[];await load()}onMounted(load)</script>
<style scoped>.toolbar{display:flex;gap:10px;margin-bottom:16px}.notice{margin-bottom:16px}</style>
